#!/bin/zsh
# Slice 1's full case set: the same Swift tests as the gate, pointed
# at .build/pins-full (every case of macTEM's fft-, spot- and hrtem-filter-parity harnesses and every angle plant,
# regenerated by tools/slice-1/pins.py) through IMAGOKIT_PINS_FULL. Run at every frozen commit and logged in docs/status.md;
# not part of CI (it needs the skimage venv and macTEM beside this repository to regenerate the pins).
#
#   ../References/python/skimage/bin/python -I -B tools/slice-1/pins.py   # when .build/pins-full is missing
#   tools/slice-1/full-parity.sh
set -euo pipefail
cd "${0:A:h}/../.."
for f in fft/ref/manifest.json spot/ref/manifest.json angle/manifest.json hrtem/ref/manifest.json; do
  [[ -f .build/pins-full/$f ]] || { print -u2 "full-parity: .build/pins-full/$f is missing; run tools/slice-1/pins.py first"; exit 1 }
done
IMAGOKIT_PINS_FULL=$PWD/.build/pins-full swift test -c release --filter ImagoKitParityTests
